diff --git a/src/io/sales-import.js b/src/io/sales-import.js
new file mode 100644
index 0000000..11ae56d
--- /dev/null
+++ b/src/io/sales-import.js
@@ -0,0 +1,49 @@
+// Till imports are staged on a copy so a bad row cannot change stock.
+import { memoryStore } from "../db/store.js";
+import { AppError } from "../errors.js";
+import { consume } from "../domain/batches.js";
+import { getDish } from "../domain/menu.js";
+import { getRecipe, scaled } from "../domain/recipes.js";
+import { t } from "../i18n/messages.js";
+import { parseCsv } from "./csv.js";
+
+/** Imports new tickets atomically and returns ticket and dish counts. */
+export function importSales(store, text) {
+  if (typeof text !== "string") throw new AppError("bad_request", { reason: "csv must be a string" });
+  const lines = text.split(/\r?\n/).map((line, i) => ({ line, number: i + 1 })).filter(({ line }) => line.trim());
+  const header = lines.shift();
+  if (!header || header.line.trim() !== "ticket,soldAt,dishId,qty")
+    throw new AppError("bad_request", { reason: "row 1: expected ticket,soldAt,dishId,qty" });
+  const staged = memoryStore(store.data);
+  const existing = new Set(staged.data.sales.map((s) => s.ticket));
+  const tickets = new Set();
+  let dishes = 0;
+  for (const { line, number } of lines) {
+    try {
+      if (!/^(?:[^",]*|"(?:[^"]|"")*")(?:,(?:[^",]*|"(?:[^"]|"")*"))*$/.test(line))
+        throw new AppError("bad_request", { reason: "invalid CSV" });
+      const fields = parseCsv(line)[0];
+      if (fields.length !== 4) throw new AppError("bad_request", { reason: "expected four columns" });
+      const [ticket, soldAt, dishText, qtyText] = fields.map((v) => v.trim());
+      if (!ticket) throw new AppError("bad_request", { reason: "ticket is required" });
+      if (!/^\d{4}-\d\d-\d\dT\d\d:\d\d:\d\d(?:\.\d+)?(?:Z|[+-]\d\d:\d\d)$/.test(soldAt) || !Number.isFinite(Date.parse(soldAt)) || new Date(soldAt.slice(0, 10) + "T00:00:00Z").toISOString().slice(0, 10) !== soldAt.slice(0, 10))
+        throw new AppError("bad_request", { reason: "invalid soldAt" });
+      if (!/^[1-9]\d*$/.test(dishText) || !Number.isSafeInteger(Number(dishText))) throw new AppError("bad_request", { reason: "invalid dishId" });
+      if (!/^[1-9]\d*$/.test(qtyText) || !Number.isSafeInteger(Number(qtyText))) throw new AppError("bad_request", { reason: "invalid qty" });
+      const dish = getDish(staged, Number(dishText));
+      const recipe = getRecipe(staged, dish.recipeId);
+      const needs = scaled(recipe, Number(qtyText));
+      if (existing.has(ticket)) continue;
+      const at = new Date(soldAt).toISOString();
+      for (const need of needs) if (need.qty > 0) consume(staged, need.itemId, need.qty, { at, ref: `sale:${ticket}` });
+      staged.data.sales.push({ ticket, soldAt: at, dishId: dish.id, qty: Number(qtyText), ingredients: needs });
+      tickets.add(ticket);
+      dishes += Number(qtyText);
+    } catch (e) {
+      if (!(e instanceof AppError)) throw e;
+      throw new AppError("bad_request", { reason: `row ${number}: ${t(e.code, "en", e.params)}` });
+    }
+  }
+  store.data = staged.data;
+  return { tickets: tickets.size, dishes };
+}
